package io.github.miclean.tests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
import io.github.miclean.module.skip.*;
public final class SkipNoticeUiSmoke extends Instrumentation {
    private Activity current;private int checks;
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void callActivityOnResume(Activity a){super.callActivityOnResume(a);current=a;}
    private void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
    private void main(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable x){e[0]=x;}});if(e[0]!=null)throw new AssertionError(e[0]);}
    private View tag(View v,String k){if(k.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=tag(((ViewGroup)v).getChildAt(i),k);if(found!=null)return found;}return null;}
    private AlertDialog dialog(){try{java.lang.reflect.Field f=current.getClass().getDeclaredField("smartSkip");f.setAccessible(true);Object panel=f.get(current);f=panel.getClass().getDeclaredField("noticeDialog");f.setAccessible(true);return (AlertDialog)f.get(panel);}catch(Exception e){throw new AssertionError(e);}}
    private void capture(){main(()->{View v=dialog().getWindow().getDecorView();android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(v.getWidth(),v.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(bitmap));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getCacheDir(),"skip-notice-dialog-0129.png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{bitmap.recycle();}});}
    @Override public void onStart(){Bundle result=new Bundle();SharedPreferences prefs=getTargetContext().getSharedPreferences("smart_skip",0),ui=getTargetContext().getSharedPreferences("miclean_ui",0);Map<String,?> before=new HashMap<>(prefs.getAll()),uiBefore=new HashMap<>(ui.getAll());
        try{for(int i=0;i<80&&current==null;i++)SystemClock.sleep(100);check(current!=null,"Main not started");SystemClock.sleep(600);
            main(()->{View root=current.getWindow().getDecorView();for(String key:new String[]{"advertising","smart_skip","skip_compact_settings"})if(tag(root,"body:"+key).getVisibility()!=View.VISIBLE)tag(root,"fold:"+key).performClick();Switch s=(Switch)tag(root,"skip_notice_enabled");check(s!=null,"Notice switch missing");boolean old=s.isChecked();s.performClick();check(prefs.getBoolean(SkipNotice.ENABLED,false)!=old,"Switch not saved");s.performClick();check(s.isChecked()==old,"Switch not restored");tag(root,"skip_notice_editor").performClick();});waitForIdleSync();capture();
            main(()->{AlertDialog d=dialog();check(d!=null&&d.isShowing(),"No custom text dialog");EditText input=(EditText)tag(d.getWindow().getDecorView(),"skip_notice_text");check(input!=null,"No input");input.setText("自定义跳过提示🙂");d.getButton(-1).performClick();});waitForIdleSync();main(()->{check("自定义跳过提示🙂".equals(prefs.getString(SkipNotice.TEXT,null)),"Text not saved");tag(current.getWindow().getDecorView(),"skip_notice_editor").performClick();});waitForIdleSync();
            main(()->{AlertDialog d=dialog();EditText input=(EditText)tag(d.getWindow().getDecorView(),"skip_notice_text");check("自定义跳过提示🙂".contentEquals(input.getText()),"Reopen lost saved text");input.setText("取消的修改");d.getButton(-2).performClick();});waitForIdleSync();main(()->{check("自定义跳过提示🙂".equals(prefs.getString(SkipNotice.TEXT,null)),"Cancel saved edits");tag(current.getWindow().getDecorView(),"skip_notice_editor").performClick();});waitForIdleSync();
            main(()->{AlertDialog d=dialog();((EditText)tag(d.getWindow().getDecorView(),"skip_notice_text")).setText(" ");d.getButton(-1).performClick();});waitForIdleSync();main(()->{check(SkipNotice.DEFAULT_TEXT.equals(prefs.getString(SkipNotice.TEXT,null)),"Blank did not restore default");});
            result.putString("stream","PASS: "+checks+" notice UI checks: independent toggle, shared dialog UI, custom text persistence, reopen, cancel and default restoration.\n");
        }catch(Throwable e){result.putString("stream","FAIL: "+e+"\n");}
        finally{SharedPreferences.Editor e=prefs.edit();for(String k:new String[]{SkipNotice.ENABLED,SkipNotice.TEXT}){if(!before.containsKey(k))e.remove(k);else if(before.get(k) instanceof Boolean)e.putBoolean(k,(Boolean)before.get(k));else e.putString(k,(String)before.get(k));}e.commit();e=ui.edit();for(String k:new String[]{"advertising","smart_skip","skip_compact_settings"}){if(uiBefore.containsKey(k))e.putBoolean(k,(Boolean)uiBefore.get(k));else e.remove(k);}e.commit();}
        finish(result.getString("stream","").startsWith("PASS:")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
